/bin/bash -lc "perl -e '
my "'$ref = q{/workspace/dataset/test9_executable};
my $rust = q{/output/test9};
my $seed = 123456789;
sub rnd { $seed = (1103515245 * $seed + 12345) & 0x7fffffff; return $seed / 0x7fffffff; }
for my $i (1..200) {
  my @vals;
  for (1..4) {
    my $x = rnd() * 4.0 - 1.5;
    push @vals, sprintf("%.8f", $x);
  }
  my $args = join q{ }, @vals;
  my $a = qx{$ref $args};
  my $b = qx{$rust $args};
  if ($a ne $b) {
    print "Mismatch'"\\n"'$args'"\\nref="'$a'"\\nrust="'$b";
    exit 1;
  }
}
print "All compared cases matched'"\\n\";
'"

